def is_palindrome(num):
    if num < 0:
        return False                # negative numbers can never be palindromes
    s = str(num)                    # convert to a string so we can index both ends
    left, right = 0, len(s) - 1     # two pointers starting at opposite ends
    while left < right:
        if s[left] != s[right]:
            return False               # first mismatch means it is not a palindrome
        left += 1                       # move the left pointer inward
        right -= 1                       # move the right pointer inward
    return True                       # pointers met without ever finding a mismatch


if __name__ == "__main__":
    num = 121
    print(is_palindrome(num))

