import java.util.*;

public class Main {
    boolean isPalindrome(int num) {
        if (num < 0) {
            return false;                    // negative numbers can never be palindromes
        }
        String s = String.valueOf(num);       // convert to a string so we can index both ends
        int left = 0, right = s.length() - 1; // two pointers starting at opposite ends
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;                    // first mismatch means it is not a palindrome
            }
            left++;                               // move the left pointer inward
            right--;                               // move the right pointer inward
        }
        return true;                            // pointers met without ever finding a mismatch
    }

    public static void main(String[] args) {
        int num = 121;
        Main solution = new Main();
        System.out.println(solution.isPalindrome(num));
    }
}

